{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows negative sentiment (e.g., -0.25) or recent price declines, as models tend to overreact to short-term volatility.",
    "Apply a mean reversion bias: if forecast is significantly above recent 5-day average, reduce by 5-10% to avoid over-optimism.",
    "Reduce forecast magnitude after a spike (e.g., >70% increase in 3 days) by 15-25% to account for overshoot and market correction.",
    "Increase forecast sensitivity to recent low prices (last 3-5 days) when sentiment is neutral or positive — models often underreact to support levels.",
    "If true outcome is consistently below forecast (e.g., 3+ consecutive days), apply a downward bias of 3-5% to avoid overestimating upward momentum.",
    "For horizon > 15 days, reduce forecast by 5-10% if sentiment history shows no recent positive signals — models overestimate long-term trends without sentiment support."
  ]
}
